"""Katyayani on Kaal `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def cell(m: dict | None) -> str:
    if not m:
        return "—"
    lo, hi = m["ci95"]
    return f"{m['value']:.3f} [{lo:.3f}, {hi:.3f}]"


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    out = [
        "<!-- Generated by packages/sati/sati/rca/kaalreport.py from the training workflow. Do not edit by hand. -->\n",
        "# Katyayani on Kaal — root cause on synthetic incidents (RP-24)\n",
        f"**{d['name']}**: {d['n']:,} incidents (seed {d['seed']}). The splits are the committed manifest's, and their "
        f"hashes were checked before training. Incidents with a root to rank: "
        + ", ".join(f"{k} {v:,}" for k, v in d["incidents_with_a_root"].items()) + ".\n",
        "| Split | Ranker | RCA@1 [95% CI] | RCA@3 [95% CI] | Fault type |",
        "|---|---|---:|---:|---:|",
    ]
    for split, rankers in r["test"].items():
        for name, m in rankers.items():
            label = f"**{name}**" if name.startswith("katyayani") else name
            out.append(f"| {split} | {label} | {cell(m['rca@1'])} | {cell(m['rca@3'])} | {cell(m.get('fault_type'))} |")
    out += [
        "",
        "## How to read this\n",
        "- **This task is close to trivial for a topology-aware ranker, and that is the finding.** When a fault "
        "propagates along the call graph, the root is the one anomalous service every other anomalous service sits "
        "above. Generator v1 adds missing telemetry, retry amplification, backpressure, onset skew and coincident "
        "anomalies. They pull the no-learning baselines down, not the ranker. The number that matters is the "
        "simulation-to-real gap.",
        f"- Simulation to real: {r['sim_to_real']}.",
        "- Fault type is the harder half. It is not reported on test-ood-fault, whose fault types the head never saw.",
        "- Designed, written and trained by an AI assistant under the owner's direction; the generator's fault model is "
        "proposed and awaits the owner's decision (adr/KaalGenerator).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
